rowdata.pyStepsJavaSource:
try {
    String stepPageName = myStepPage.getReference();
    boolean isPyWorkPage = "pyWorkPage".equals(stepPageName);
    ParameterPage pp = tools.getParameterPage();
    if (!myStepPage.getProperty("skipDCDataModelUpdation").toBoolean() && !isPyWorkPage) {
        myStepPage.putString("skipDCDataModelUpdation", tools.getParamValue("skipDCDataModelUpdation"));
    }

    // SE-53767 : Skip parameter page updation if pyWorkPage.
    if (!isPyWorkPage) {
        pp.put("skipDCDataModelUpdation", myStepPage.getProperty("skipDCDataModelUpdation"));
    }
} catch (Exception ex) {}

ClipboardPage cpFlowTracerPage = tools.findPage("FlowDebuggerPage");

ParameterPage pp = tools.getParameterPage();
Set propertySet = cpFlowTracerPage.keySet();
Iterator it = propertySet.iterator();
while (it.hasNext()) {
	String pName = (String) it.next();
	if(!pName.equalsIgnoreCase("SkipFlowDebuggerOverride")) {
		pp.putString(pName, cpFlowTracerPage.getString(pName));
	}
}

String strFrameName = StringUtils.crossScriptingFilter(tools.getParamValue("CustomFrameName"));
String strRequestorFrame = StringUtils.crossScriptingFilter(tools.getParamValue("pzFromFrame"));

if (strFrameName.equals("")){
	if(myStepPage!= null && myStepPage.getName() != null && !myStepPage.getName().equals("")){
		strFrameName = 	myStepPage.getName();
	}else{
		strFrameName = "pyWorkPage";
	}
         if(strRequestorFrame != null && strRequestorFrame!= "" ) {
		strFrameName = strRequestorFrame; 
	}

}
tools.preventStaleHTTPRequestProcessing(strFrameName );

bJSRCompliant = false;
ClipboardPage primaryPage = tools.getPrimaryPage();
StringMap  keys = new HashStringMap();
keys.putString("pyClassName", primaryPage.getString("pxObjClass"));
keys.putString("pyStreamName", tools.getParamValue("Purpose"));
keys.putString("pxObjClass", "Rule-HTML-Harness");
try 
{
	ClipboardPage  instance = tools.getDatabase().open(keys, true);
	if (instance != null) 
	{
			bJSRCompliant = instance.getProperty("pyJSRCompliant").toBoolean();
	}
} 
catch (DatabaseException aErr) 
{
}

tools.openHTMLDoc();// open a new HTML doc to reset onlyonce (pzSetAll)settings
StringMap keys = new HashStringMap();
String strHTMLClass = StringUtils.crossScriptingFilter(tools.getParamValue("HTMLClass"));
if (strHTMLClass == null || strHTMLClass.equals("")) {
	strHTMLClass = "Rule-HTML-Harness";
	tools.putParamValue("HTMLClass", strHTMLClass);
}

// Begin FlowDebugger
boolean bDisplayFlowDebugger = (pega_rules_settings.IsFlowDebuggerEnabled() && 
				(!tools.getParamValue("SkipFlowDebuggerOverride").equalsIgnoreCase("TRUE"))  );

if(bDisplayFlowDebugger && 
			!tools.getPrimaryPage().getName().equals("propertyPanelPage")) {	// If we are in flowTrace mode
	ClipboardPage cpFlowTracerPage = tools.findPage("FlowDebuggerPage", false);	// Get the page (or make it)

	cpFlowTracerPage.copyParameterValues(tools.getParameterPage());

	keys.putString("pxObjClass",  "Rule-Obj-HTML");
	keys.putString("pyStreamName", "FlowDebuggerFrameset");
	keys.putString("PrimaryPage", tools.getPrimaryPage().getName());

} else {
	if( tools.getParamValue("Purpose").equals("FlowDebuggerStep") )		// If this is the step harness, we must set pyClassName as well.
		keys.putString("pyClassName", StringUtils.crossScriptingFilter(tools.getParamValue("InsClass")));
	keys.putString("pxObjClass", strHTMLClass); 
         tools.putParamValue("pyDispatchStream", "true");
	keys.putString("pyStreamName", StringUtils.crossScriptingFilter(tools.getParamValue("Purpose")));	
	tools.putParamValue("streamKeys", keys.toString());
}
// End FlowDebugger

// ReadOnly takes precedence over HarnessMode
String readOnly = tools.getParamValue("ReadOnly");
if (readOnly != null && (readOnly.equalsIgnoreCase("-1")||readOnly.equalsIgnoreCase("true")))
{
        keys.putString("pzInput", StreamBuilder.sNoInput);
}
else
{
    String harnessMode = tools.getParamValue("HarnessMode");
    if (harnessMode != null && harnessMode.equalsIgnoreCase("ACTION"))
    {
        keys.putString("pzInput", StreamBuilder.sNoInput);
        tools.putParamValue("ReadOnly", "-1");
    }
    else
    {
        keys.putString("pzInput", StreamBuilder.sInputEnabled);
    }
}

ClipboardPage threadPage = tools.getThread().getThreadPage();


/* Frame name - usually "pyWorkPage"
   CustomFrameName is set by the current request if harness being shown intends
   to commit the current txn without affecting the txn associated with pyWorkPage.
   Ref- PMF BUG-2525
*/
String strFrameName = StringUtils.crossScriptingFilter(tools.getParamValue("CustomFrameName"));
String strRequestorFrame = StringUtils.crossScriptingFilter(tools.getParamValue("pzFromFrame"));

if (strFrameName.equals("")){
	if(myStepPage!= null && myStepPage.getName() != null && !myStepPage.getName().equals("")){
		strFrameName = 	myStepPage.getName();
	}else{
		strFrameName = "pyWorkPage";
	}
         if(strRequestorFrame != null && !strRequestorFrame.equals("") ) {
		strFrameName = strRequestorFrame; 
	}

}
threadPage.putString("pyHTMLFrame", strFrameName);

//BUG-119491 coordinate pxClientFrame and pyHTMLFrame for modal popup windows
//BUG-135222- removing prevent stale requestor call to step3 the way it was  befor
String clientframe  = threadPage.getString("pxClientFrame"); 
if (strFrameName!= null && clientframe  == null)
    threadPage.putString("pxClientFrame",strFrameName);
else if (strFrameName!= null && clientframe  != null  && strFrameName.contentEquals(clientframe))
    threadPage.putString("pxClientFrame",strFrameName);

// Display the stream
String stream = null;
try 
{
	tools.putParamValue("streamKeys2", keys.toString());
	stream = tools.getStream(keys, null);
}
catch (ActivityTerminateException e) 
{
	throw e;
}
catch (Throwable e) 
{			
	tools.openHTMLDoc();// open a new HTML doc to reset onlyonce (pzSetAll)settings
	if (e instanceof PRRuntimeError)  
		tools.putParamValue("ErrorMessage", e.getMessage());
	else if (e instanceof PRRuntimeException)
	{
		if ((e.getMessage().indexOf("Failed to find instance") > -1) && tools.getParamAsBoolean(PropertyInfo.TYPE_TRUEFALSE, "DraftMode") == true && !tools.getParamValue("HarnessType").equals("") && !tools.getParamValue("HarnessType").equals(tools.getParamValue("Purpose")))
		{
			// Just show the harness of the specified type; we don't show errors in draft mode.
			tools.putParamValue("Purpose", StringUtils.crossScriptingFilter(tools.getParamValue("HarnessType")));
			pega_rules_utilities.callActivity(myStepPage, "Show-Harness", tools.getParameterPage());
			return false;
		}
		else
			tools.putParamValue("ErrorMessage", e.getMessage());
	}
	else if (e instanceof PRAppRuntimeException)
		tools.putParamValue("ErrorMessage", e.getMessage());
	else
	{
		// the java errors & exceptions, like NullPointerException, don't have a message
		// so we have to use toString instead
		tools.putParamValue("ErrorMessage", e.toString());
	}

	ClipboardPage assignPage = tools.findPage("newAssignPage");
	if (assignPage != null) {
		String formName = assignPage.getString(".pxFormName");
		// check if this is a perform harness; if so mark assignment as problem assignment
		if (formName.equals(tools.getParamValue("Purpose"))) {
			String errMessage = tools.getParamValue("ErrorMessage");
			pega_procom_pegaprocomutilities.markProblemAssignment(assignPage, "Harness Fail", errMessage, tools);
		}
		tools.putParamValue("flowName", assignPage.getString(".pxFlowName"));
		tools.putParamValue("FlowStep", assignPage.getString(".pxTaskName"));
	}			

	tools.putParamValue("ReadOnly", keys.getString("pzInput"));
	tools.putParamValue("StackTrace", pega_rules_utilities.getStackTrace(e));
	keys.putString("pyStreamName", "HarnessFail");
	stream = tools.getStream(keys, null);

}

if (stream != null) {
	if (threadPage.containsKey("pxHTMLStream"))
		oLog.alert("PEGA0031", "Overwritten HTML stream", 0, 0, null, null);
		threadPage.putString("pxHTMLStream", stream);
} else {
	threadPage.putString("pyXMLStream", "No stream to display");
}
